import 'package:flutter/material.dart'; import '../core/api_client.dart';
class AssignmentsScreen extends StatelessWidget { const AssignmentsScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('My Deliveries')), body: FutureBuilder<Map<String, dynamic>>(future: ApiClient().assignments(), builder: (_, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); final rows = ((snapshot.data?['data'] as Map<String, dynamic>?)?['data'] as List<dynamic>? ?? []); if (rows.isEmpty) return const Center(child: Text('No delivery assignments yet.')); return ListView.separated(padding: const EdgeInsets.all(16), itemCount: rows.length, separatorBuilder: (_, __) => const SizedBox(height: 10), itemBuilder: (_, i) { final row = rows[i] as Map<String, dynamic>; final order = row['order'] as Map<String, dynamic>? ?? {}; return Card(child: ListTile(leading: const CircleAvatar(child: Icon(Icons.delivery_dining)), title: Text(order['order_number']?.toString() ?? 'Delivery'), subtitle: Text('${row['status']} • ${order['address']?['address_line'] ?? 'Customer address'}'), trailing: const Icon(Icons.chevron_right), onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => AssignmentDetail(data: row)))); }); })); }
class AssignmentDetail extends StatefulWidget { const AssignmentDetail({super.key, required this.data}); final Map<String, dynamic> data; @override State<AssignmentDetail> createState() => _AssignmentDetailState(); }
class _AssignmentDetailState extends State<AssignmentDetail> { final otp = TextEditingController(); bool busy = false; Future<void> update(String status) async { setState(() => busy = true); try { await ApiClient().updateAssignment(widget.data['id'] as int, status, pickupOtp: status == 'picked_up' ? otp.text : null, deliveryOtp: status == 'delivered' ? otp.text : null); if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Delivery status updated.'))); } finally { if (mounted) setState(() => busy = false); } }
  @override Widget build(BuildContext context) { final order = widget.data['order'] as Map<String, dynamic>? ?? {}; return Scaffold(appBar: AppBar(title: Text(order['order_number']?.toString() ?? 'Delivery')), body: ListView(padding: const EdgeInsets.all(16), children: [Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Pickup', style: TextStyle(fontWeight: FontWeight.bold)), Text(order['outlet']?['address_line']?.toString() ?? 'Store location'), const Divider(height: 28), const Text('Drop', style: TextStyle(fontWeight: FontWeight.bold)), Text(order['address']?['address_line']?.toString() ?? 'Customer location')]))), const SizedBox(height: 12), TextField(controller: otp, keyboardType: TextInputType.number, maxLength: 6, decoration: const InputDecoration(labelText: 'Pickup / Delivery OTP', prefixIcon: Icon(Icons.password))), const SizedBox(height: 8), ElevatedButton(onPressed: busy ? null : () => update('accepted'), child: const Text('Accept Assignment')), const SizedBox(height: 8), OutlinedButton(onPressed: busy ? null : () => update('picked_up'), child: const Text('Confirm Pickup')), const SizedBox(height: 8), OutlinedButton(onPressed: busy ? null : () => update('delivered'), child: const Text('Confirm Delivery'))])); } }

